 static void terminalize(NativeReplacementContinuationTest.Fresh fresh,NativeFaultedJobReplacement.ContinuationPermit permit)throws Exception {
  fresh.revoke();permit.close();Map<String,Object> terminal=NativeReplacementContinuationTest.freshOperation(fresh);terminal.put("state","outcome_unknown");terminal.put("native_completion",NativeFaultedJobReplacement.map("native_wrapper_completed",true,"native_wrapper_succeeded",false,"physical_outcome_verified",false));fresh.fixture.e.append("operation",terminal);fresh.fixture.e.terminalWrappers.add(fresh.operation);
 }
 static void refusedFreshChangedTarget(NativeReplacementContinuationTest.Fixture f,NativeFaultedJobReplacement.ContinuationPermit permit,String old,boolean stillActive,String why)throws Exception {
  task(()->{permit.check();Map<String,Object> captured=o(permit.authorizeMaterial(f.e.material,old).get("phase_row"));yes("completed".equals(captured.get("phase"))&&Boolean.FALSE.equals(captured.get("current_matches_replacement_receipt"))&&Boolean.valueOf(stillActive).equals(captured.get("replacement_still_active")),"Fresh decision captures the actual changed material state for "+why);
   for(Object raw:(List<?>)f.e.material.snapshot().get("continuation_adoption_receipts"))yes(!permit.continuationId().equals(o(raw).get("continuation_id")),"Fresh decision has no prior adoption receipt that could cause duplicate refusal");
   unchangedRefusal(f,why,()->{try{f.e.material.adoptCompletedReplacement(permit,old);throw new AssertionError("Fresh changed target accepted");}catch(Bridge.Fault error){yes("MATERIAL_CONTINUATION_SCOPE".equals(error.code),"Fresh changed target is refused by material state guard, not a duplicate or stale permit");throw error;}});return null;});
 }
